SELECT COUNT(DISTINCT product_category_name) AS category_count
FROM products
WHERE product_category_name IS NOT NULL;

SELECT COUNT(*) AS product_cnt
FROM products
WHERE product_weight_g > 5000;

SELECT COUNT(*) AS item_count
FROM order_items
WHERE price < 10;

SELECT COUNT(*) AS urgent_tickets
FROM support_tickets
WHERE priority = '4';

SELECT COUNT(*) AS 库存不足记录数
FROM inventory
WHERE quantity < safety_stock;

SELECT COUNT(*) AS order_count
FROM orders
WHERE order_purchase_timestamp >= (
    SELECT MAX(order_purchase_timestamp)::date - INTERVAL '89 days'
    FROM orders
  )
  AND order_purchase_timestamp < (
    SELECT MAX(order_purchase_timestamp)::date + INTERVAL '1 day'
    FROM orders
  );

SELECT COUNT(*) AS late_order_count
FROM orders
WHERE order_delivered_customer_date > order_estimated_delivery_date;
